+import type { Book } from '../../types';
+import './BookCard.css';
+
+interface BookCardProps {
+  book: Book;
+  onClick: (id: string) => void;
+}
+
+export function BookCard({ book, onClick }: BookCardProps) {
+  const displayBook = book as Book;
+  return (
+    <article
+      className="book-card"
+      role="button"
+      tabIndex={0}
+      aria-label={`${displayBook.title} by ${displayBook.author}`}
+      onClick={() => onClick(displayBook.id)}
+    >
+      <h3>{displayBook.title}</h3>
+      <p>{displayBook.author}</p>
+    </article>
+  );
+}
